-- 감칠맛(umami)과 짠맛(saltiness)은 더 이상 카탈로그의 감각 차원이 아니다.
-- The questionnaire stopped asking the two tastes on 2026-10-24 and the card
-- never explains them, so the two level columns go, together with every stored
-- fact, semantic entry and source word that named them and the validators that
-- listed them. Descriptor vocabulary such as concentrated_umami or saline is a
-- flavour word, not a dimension, and stays.

-- 1. Stored data that named the two axes. The working copy was cleaned and
--    synced first, so these normally touch nothing; they make the migration
--    safe on its own. Only the structured columns change, so the source-change
--    trigger does not fire.
update public.alcohol_tasting_profiles
  set level_sources = level_sources - 'umami' - 'saltiness'
  where level_sources ?| array['umami', 'saltiness'];

update public.alcohol_tasting_profiles
  set structured_sensory = jsonb_set(structured_sensory, '{facts}', coalesce(
    (select jsonb_agg(f) from jsonb_array_elements(structured_sensory->'facts') f where not (f#>>'{target,kind}' = 'axis' and f#>>'{target,key}' in ('umami','saltiness'))), '[]'::jsonb))
  where structured_sensory is not null
    and exists (select 1 from jsonb_array_elements(structured_sensory->'facts') f where not (not (f#>>'{target,kind}' = 'axis' and f#>>'{target,key}' in ('umami','saltiness'))));

update public.alcohol_tasting_profiles
  set structured_semantics = jsonb_set(structured_semantics, '{entries}', coalesce(
    (select jsonb_agg(e) from jsonb_array_elements(structured_semantics->'entries') e where not (e#>>'{identity,target,kind}' = 'axis' and e#>>'{identity,target,key}' in ('umami','saltiness')) and not (e#>>'{identity,from,kind}' = 'axis' and e#>>'{identity,from,key}' in ('umami','saltiness')) and not (e#>>'{identity,to,kind}' = 'axis' and e#>>'{identity,to,key}' in ('umami','saltiness'))), '[]'::jsonb))
  where structured_semantics is not null
    and exists (select 1 from jsonb_array_elements(structured_semantics->'entries') e where not (not (e#>>'{identity,target,kind}' = 'axis' and e#>>'{identity,target,key}' in ('umami','saltiness')) and not (e#>>'{identity,from,kind}' = 'axis' and e#>>'{identity,from,key}' in ('umami','saltiness')) and not (e#>>'{identity,to,kind}' = 'axis' and e#>>'{identity,to,key}' in ('umami','saltiness'))));

-- 2. Validators and helpers that listed the two axes.
create or replace function public.valid_product_sensory_facts(p jsonb, item_id uuid)
 RETURNS boolean
